"use client";
import { useState } from "react";
import { buildCampaign, getRank, tierConfig } from "./questionBank";

export default function Home() {
  const [screen, setScreen] = useState("home"), [mode, setMode] = useState("dsa"), [level, setLevel] = useState(0), [choice, setChoice] = useState(null), [lives, setLives] = useState(3), [xp, setXp] = useState(0), [hint, setHint] = useState(false), [message, setMessage] = useState("");
  const campaign = buildCampaign(mode), current = campaign[level], rank = getRank(xp), tier = tierConfig[current?.tier || 0];
  function start(nextMode = "dsa") { setMode(nextMode); setScreen("game"); setLevel(0); setChoice(null); setLives(3); setXp(0); setHint(false); setMessage(""); }
  function next() { if (level === campaign.length - 1) setScreen("win"); else { setLevel(level + 1); setChoice(null); setHint(false); setMessage(""); } }
  function submit() { if (choice === current.answer) { setXp(xp + current.xpReward); setMessage(`LEVEL CLEAR  +${current.xpReward} XP`); setTimeout(next, 650); return; } const remaining = lives - 1; setLives(remaining); setChoice(null); setMessage(remaining ? "LIFE LOST — TRY AGAIN" : "OUT OF LIVES"); if (!remaining) setTimeout(() => setScreen("lost"), 700); }
  return <main className={`shell ${screen === "home" ? "storefront" : ""}`}><div className="grid-bg" />
    <header className="topbar"><button className="wordmark" onClick={() => setScreen("home")}><span>BQ</span> BYTEQUEST</button><nav><a href="#quests">Quests</a><a href="#benefits">Rewards</a><a href="#about">How it works</a></nav><div className="account"><span className="online"><i /> ONLINE</span><button onClick={start}>PLAY NOW</button></div></header>
    {screen === "home" && <><section className="choice-hero"><div className="hero-copy"><p className="eyebrow">BYTEQUEST <b>CHOICE</b></p><h1>CODE MORE.<br/>LEVEL UP <em>FASTER.</em></h1><p>A fresh collection of C and DSA challenges in one evolving adventure. Keep your rewards, build your streak, and master every quest.</p><button className="hero-cta" onClick={start}>START YOUR QUEST</button><small>No download required · Play in your browser</small></div><div className="hero-art" aria-hidden="true"><div className="orb"/><div className="cover cover-one"><small>DSA</small><b>ALGORITHM<br/>ASCENT</b><span>01</span></div><div className="cover cover-two"><small>C CODE</small><b>THE<br/>FORGE</b><span>02</span></div><div className="cover cover-three"><small>DEBUG</small><b>BUG<br/>HUNTER</b><span>03</span></div></div></section><section className="monthly" id="quests"><div className="section-title"><div><p>THIS CAMPAIGN</p><h2>Three ways to play</h2></div><span>6 hand-picked levels</span></div><div className="game-shelf"><button className="game-tile tile-dsa" onClick={start}><span className="tile-tag">KNOWLEDGE</span><div>?</div><h3>DSA TRIALS</h3><p>Think fast. Choose wisely.</p></button><button className="game-tile tile-code" onClick={start}><span className="tile-tag">CODE REPAIR</span><div>&lt;/&gt;</div><h3>CODE FORGE</h3><p>Complete real C programs.</p></button><button className="game-tile tile-bug" onClick={start}><span className="tile-tag">BUG FIX</span><div>!</div><h3>BUG HUNT</h3><p>Track down dangerous errors.</p></button></div></section><section className="benefits" id="benefits"><p className="eyebrow">YOUR ADVENTURE, YOUR PROGRESS</p><h2>Everything you earn stays with the run</h2><div className="benefit-grid"><article><i>♥</i><h3>Three lives</h3><p>Make mistakes, learn, and fight back before your run ends.</p></article><article><i>XP</i><h3>Level up</h3><p>Earn experience for every cleared challenge and build your rank.</p></article><article><i>💡</i><h3>Smart hints</h3><p>Get a useful nudge when a puzzle has you completely stuck.</p></article></div></section><section className="final-cta" id="about"><p>READY FOR YOUR NEXT CHALLENGE?</p><h2>Your coding adventure starts here.</h2><button className="hero-cta" onClick={start}>PLAY BYTEQUEST</button></section></>}
    {screen === "game" && <section className="game"><aside><small>CURRENT QUEST</small><h3>{current.type}</h3><div className="counter"><b>{String(level + 1).padStart(2,"0")}</b> / {String(levels.length).padStart(2,"0")}</div><div className="bar"><i style={{width:`${(level / levels.length) * 100}%`}}/></div><div className="player-stats"><span>XP <b>{xp}</b></span><span>LEVEL <b>{Math.floor(xp / 300) + 1}</b></span></div><div className="life"><span className="hearts">{"♥".repeat(lives)}{"♡".repeat(3-lives)}</span><span><b>{lives} LIVES LEFT</b><small>WRONG ANSWERS COST ONE</small></span></div><button onClick={() => setScreen("home")}>× EXIT QUEST</button></aside><article><div className="panel-head"><span>LEVEL_{String(level + 1).padStart(2,"0")}</span><b>{current.type}</b></div><h2>{current.title}</h2>{current.code && <div className="editor"><div><i/><i/><i/><span>challenge.c</span></div><pre>{current.code}</pre></div>}<p className="instruction">{current.prompt}</p><div className="options">{current.choices.map((item, i) => <button key={item} className={choice === i ? "active" : ""} onClick={() => setChoice(i)}><b>{String.fromCharCode(65 + i)}</b>{item}<i>→</i></button>)}</div><div className="submit"><button className="hint-button" onClick={() => setHint(!hint)}>💡 {hint ? "HIDE HINT" : "USE HINT"}</button><span className={message.includes("CLEAR") ? "success" : "error"}>{message}</span><button className="primary" disabled={choice === null || message.includes("CLEAR")} onClick={submit}>CONFIRM →</button></div>{hint && <p className="hint">// HINT: {current.hint}</p>}</article></section>}
    {(screen === "win" || screen === "lost") && <section className={`ending ${screen === "lost" ? "lost" : ""}`}><code>{screen === "win" ? "QUEST_COMPLETE" : "RUN_ENDED"}</code><h2>{screen === "win" ? "QUEST\nCLEARED." : "OUT OF\nLIVES."}</h2><p>{screen === "win" ? `You collected ${xp} XP across every level type.` : "Refill your hearts and take another run."}</p><button className="primary" onClick={start}>PLAY AGAIN</button><button className="ghost" onClick={() => setScreen("home")}>LOBBY</button></section>}
    <footer><span>© 2026 BYTEQUEST</span><span>LEARN C · MASTER DSA · FIX BUGS</span></footer></main>;
}
